From fa99fcf70058d89b6cb49c26fea2392ed311b558 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:18:13 +0100
Subject: [PATCH] applets/appmenu: move menus that don't fit into an overflow
 menu

The Global Menu asked the panel for the width of all its menus, so apps
with many menus pushed the tray and clock off the panel. It now needs
room for one button only and puts the menus that don't fit in a menu.

BUG: 396404
---
 applets/appmenu/appmenuapplet.cpp | 37 +++++++++++++++-
 applets/appmenu/appmenuapplet.h   | 10 ++++-
 applets/appmenu/qml/main.qml      | 72 ++++++++++++++++++++++++++++++-
 3 files changed, 114 insertions(+), 5 deletions(-)

diff --git a/applets/appmenu/appmenuapplet.cpp b/applets/appmenu/appmenuapplet.cpp
index 79c29a7e32..ee0c787942 100644
--- a/applets/appmenu/appmenuapplet.cpp
+++ b/applets/appmenu/appmenuapplet.cpp
@@ -61,7 +61,10 @@ AppMenuApplet::AppMenuApplet(QObject *parent, const KPluginMetaData &data, const
     });
 }

-AppMenuApplet::~AppMenuApplet() = default;
+AppMenuApplet::~AppMenuApplet()
+{
+    delete m_overflowMenu;
+}

 void AppMenuApplet::init()
 {
@@ -119,7 +122,20 @@ void AppMenuApplet::setButtonGrid(QQuickItem *buttonGrid)
     }
 }

-QMenu *AppMenuApplet::createMenu(int idx) const
+int AppMenuApplet::overflowIndex() const
+{
+    return m_overflowIndex;
+}
+
+void AppMenuApplet::setOverflowIndex(int overflowIndex)
+{
+    if (m_overflowIndex != overflowIndex) {
+        m_overflowIndex = overflowIndex;
+        Q_EMIT overflowIndexChanged();
+    }
+}
+
+QMenu *AppMenuApplet::createMenu(int idx)
 {
     QMenu *menu = nullptr;

@@ -127,6 +143,23 @@ QMenu *AppMenuApplet::createMenu(int idx) const
         if (auto *menuAction = m_model->data(QModelIndex(), AppMenuModel::ActionRole).value<QAction *>()) {
             menu = menuAction->menu();
         }
+    } else if (view() == FullView && idx == m_model->rowCount() && m_overflowIndex >= 0 && m_overflowIndex < idx) {
+        // The overflow button lists the menus that don't fit as submenus
+        if (!m_overflowMenu) {
+            m_overflowMenu = new QMenu;
+        }
+        QMenu *oldMenu = m_sourceMenu == m_overflowMenu ? m_currentMenu.data() : m_overflowMenu.data();
+        if (oldMenu) {
+            for (QAction *action : oldMenu->actions()) {
+                oldMenu->removeAction(action);
+            }
+        }
+        for (int i = m_overflowIndex; i < idx; ++i) {
+            if (auto *action = m_model->data(m_model->index(i, 0), AppMenuModel::ActionRole).value<QAction *>()) {
+                m_overflowMenu->addAction(action);
+            }
+        }
+        menu = m_overflowMenu;
     } else if (view() == FullView) {
         const QModelIndex index = m_model->index(idx, 0);
         if (auto *action = m_model->data(index, AppMenuModel::ActionRole).value<QAction *>()) {
diff --git a/applets/appmenu/appmenuapplet.h b/applets/appmenu/appmenuapplet.h
index 7260514b34..d8cba31957 100644
--- a/applets/appmenu/appmenuapplet.h
+++ b/applets/appmenu/appmenuapplet.h
@@ -27,6 +27,8 @@ class AppMenuApplet : public Plasma::Applet

     Q_PROPERTY(QQuickItem *buttonGrid READ buttonGrid WRITE setButtonGrid NOTIFY buttonGridChanged)

+    Q_PROPERTY(int overflowIndex READ overflowIndex WRITE setOverflowIndex NOTIFY overflowIndexChanged)
+
 public:
     enum ViewType {
         FullView,
@@ -43,6 +45,9 @@ public:
     QQuickItem *buttonGrid() const;
     void setButtonGrid(QQuickItem *buttonGrid);

+    int overflowIndex() const;
+    void setOverflowIndex(int overflowIndex);
+
     QAbstractItemModel *model() const;
     void setModel(QAbstractItemModel *model);

@@ -54,6 +59,7 @@ Q_SIGNALS:
     void viewChanged();
     void currentIndexChanged();
     void buttonGridChanged();
+    void overflowIndexChanged();
     void requestActivateIndex(int index);

 public Q_SLOTS:
@@ -63,14 +69,16 @@ protected:
     bool eventFilter(QObject *watched, QEvent *event) override;

 private:
-    QMenu *createMenu(int idx) const;
+    QMenu *createMenu(int idx);
     void setCurrentIndex(int currentIndex);
     void onMenuAboutToHide();

     int m_currentIndex = -1;
     int m_viewType = FullView;
+    int m_overflowIndex = -1;
     QPointer<QMenu> m_currentMenu;
     QPointer<QMenu> m_sourceMenu;
+    QPointer<QMenu> m_overflowMenu;
     QPointer<QQuickItem> m_buttonGrid;
     QPointer<QAbstractItemModel> m_model;
     static int s_refs;
diff --git a/applets/appmenu/qml/main.qml b/applets/appmenu/qml/main.qml
index e9f5280a3f..13a41e3b34 100644
--- a/applets/appmenu/qml/main.qml
+++ b/applets/appmenu/qml/main.qml
@@ -64,8 +64,38 @@ PlasmoidItem {
             }
         }

+        // Menus from this index on don't fit and go into the overflow button
+        readonly property int overflowIndex: {
+            if (root.vertical || menusWidth <= width) {
+                return buttonRepeater.count;
+            }
+            let usedWidth = overflowButton.implicitWidth;
+            for (let i = 0; i < buttonRepeater.count; ++i) {
+                const button = buttonRepeater.itemAt(i) as MenuDelegate;
+                if (button?.shown) {
+                    usedWidth += button.implicitWidth;
+                    if (usedWidth > width) {
+                        return i;
+                    }
+                }
+            }
+            return buttonRepeater.count;
+        }
+
+        readonly property real menusWidth: {
+            let menusWidth = 0;
+            for (let i = 0; i < buttonRepeater.count; ++i) {
+                const button = buttonRepeater.itemAt(i) as MenuDelegate;
+                if (button?.shown) {
+                    menusWidth += button.implicitWidth;
+                }
+            }
+            return menusWidth;
+        }
+
         LayoutMirroring.enabled: Application.layoutDirection === Qt.RightToLeft
-        Layout.minimumWidth: implicitWidth
+        Layout.minimumWidth: root.vertical || buttonRepeater.count === 0 ? implicitWidth : overflowButton.implicitWidth
+        Layout.preferredWidth: root.vertical || buttonRepeater.count === 0 ? -1 : menusWidth
         Layout.minimumHeight: implicitHeight

         flow: root.vertical ? GridLayout.TopToBottom : GridLayout.LeftToRight
@@ -79,9 +109,24 @@ PlasmoidItem {
             restoreMode: Binding.RestoreNone
         }

+        Binding {
+            target: Plasmoid
+            property: "overflowIndex"
+            value: buttonGrid.overflowIndex
+            restoreMode: Binding.RestoreNone
+        }
+
         Connections {
             target: Plasmoid
             function onRequestActivateIndex(index: int) {
+                if (index >= buttonGrid.overflowIndex && index <= buttonRepeater.count) {
+                    if (Plasmoid.currentIndex === buttonRepeater.count && index < buttonRepeater.count) {
+                        index = buttonGrid.overflowIndex - 1;
+                    } else {
+                        overflowButton.activated();
+                        return;
+                    }
+                }
                 const button = buttonRepeater.itemAt(index) as MenuDelegate;
                 if (button) {
                     button.activated();
@@ -92,6 +137,10 @@ PlasmoidItem {
         Connections {
             target: Plasmoid
             function onActivated() {
+                if (buttonGrid.overflowIndex === 0) {
+                    overflowButton.activated();
+                    return;
+                }
                 const button = buttonRepeater.itemAt(0) as MenuDelegate;
                 if (button) {
                     button.activated();
@@ -116,6 +165,7 @@ PlasmoidItem {
                 required property string activeMenu
                 required property PlasmaCore.Action activeActions
                 readonly property int buttonIndex: index
+                readonly property bool shown: text !== "" && (activeActions?.visible ?? false)

                 Layout.fillWidth: root.vertical
                 Layout.fillHeight: !root.vertical
@@ -123,7 +173,7 @@ PlasmoidItem {
                 Kirigami.MnemonicData.active: altState.pressed

                 down: Plasmoid.currentIndex === index
-                visible: text !== "" && (activeActions?.visible ?? false)
+                visible: shown && index < buttonGrid.overflowIndex

                 menuIsOpen: Plasmoid.currentIndex !== -1
                 onActivated: Plasmoid.trigger(this, index)
@@ -135,6 +185,24 @@ PlasmoidItem {
                 }
             }
         }
+        MenuDelegate {
+            id: overflowButton
+            readonly property int buttonIndex: buttonRepeater.count
+
+            Layout.fillHeight: true
+            visible: buttonGrid.overflowIndex < buttonRepeater.count
+            Accessible.name: i18nc("@action:button", "More Menus")
+            down: Plasmoid.currentIndex === buttonIndex
+            menuIsOpen: Plasmoid.currentIndex !== -1
+            onActivated: Plasmoid.trigger(this, buttonIndex)
+
+            contentItem: Kirigami.Icon {
+                implicitWidth: Kirigami.Units.iconSizes.small
+                implicitHeight: Kirigami.Units.iconSizes.small
+                source: "overflow-menu"
+                color: overflowButton.menuState === MenuDelegate.State.Rest ? Kirigami.Theme.textColor : Kirigami.Theme.highlightedTextColor
+            }
+        }
         Item {
             Layout.preferredWidth: 0
             Layout.preferredHeight: 0
-- 
